import fs from "fs";
import os from "os";
import path from "path";

import { compressCmaps } from "../../../external/cmapscompress/compress.mjs";

const DEFAULT_COMMENT =
  "Copyright 1990-2009 Adobe Systems Incorporated.\n" +
  "All rights reserved.\n" +
  "See ./LICENSE";

