  const lines = ["begincmap", `/CMapType ${type} def`, `/WMode ${wmode} def`];
  if (usecmap !== null) {
    lines.push(`/${usecmap} usecmap`);
  }
  lines.push(...records, "endcmap");
  return lines.join("\n");
}

function record(count, kind, lines) {
  return [`${count} begin${kind}`, ...lines, `end${kind}`].join("\n");
}

describe("compressCmaps output format", () => {
  let roots;
  let logSpy;

  beforeEach(() => {
    roots = [];
    logSpy = jest.spyOn(console, "log").mockImplementation(() => {});
  });

  afterEach(() => {
    logSpy.mockRestore();
    for (const root of roots) {
      fs.rmSync(root, { recursive: true, force: true });
    }
  });

  function makeDirectories() {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), "pdfjs-cmapscompress-"));
    roots.push(root);
    const sourceDir = path.join(root, "source");
    const destDir = path.join(root, "dest");
    fs.mkdirSync(sourceDir);
    fs.mkdirSync(destDir);
    return { sourceDir, destDir };
  }

  function compressOne(content, name = "input") {
    const { sourceDir, destDir } = makeDirectories();
    fs.writeFileSync(path.join(sourceDir, name), content);
    compressCmaps(sourceDir, destDir);
    return {
      sourceDir,
      destDir,
      hex: fs.readFileSync(path.join(destDir, `${name}.bcmap`)).toString("hex"),
    };
  }

  function outputBody(hex) {
    return hex.slice(2 + COMMENT_RECORD.length);
  }

  it("writes the header and the standard comment for an empty CMap", () => {
    const { destDir, hex } = compressOne(buildCMap());

    expect(hex).toBe(`02${COMMENT_RECORD}`);
    expect(fs.readFileSync(path.join(destDir, "input.bcmap"))).toHaveLength(
      hex.length / 2
    );
  });

  it("encodes the CMap type and writing mode in the header byte", () => {
    const { hex } = compressOne(buildCMap({ type: 2, wmode: 1 }));

    expect(hex).toBe(`05${COMMENT_RECORD}`);
  });

  it("encodes the usecmap identifier", () => {
    const { hex } = compressOne(buildCMap({ usecmap: "Identity-H" }));

    expect(outputBody(hex)).toBe("e10a4964656e746974792d48");
  });

  const recordCases = [
    [
      "codespacerange with a single-byte code space",
      record(1, "codespacerange", ["<00> <ff>"]),
      "000100817f",
    ],
    [
      "codespacerange with a two-byte code space",
      record(1, "codespacerange", ["<0000> <ffff>"]),
      "0101000083ff7f",
    ],
    [
      "notdefrange",
      record(1, "notdefrange", ["<00> <1f> 5"]),
      "2001001f05",
    ],
    [
      "cidchar",
      record(2, "cidchar", ["<20> 100", "<22> 102"]),
      "400220640102",
    ],
    [
      "cidrange",
      record(2, "cidrange", ["<20> <2f> 100", "<30> <3f> 200"]),
      "6002200f64000f8148",
    ],
    [
      "bfchar",
      record(2, "bfchar", ["<0041> <0061>", "<0042> <0062>"]),
      "8102004100610000",
    ],
    [
      "bfrange",
      record(2, "bfrange", ["<0041> <005a> <0061>", "<0061> <007a> <0041>"]),
      "a102004119006106190041",
    ],
  ];

  it.each(recordCases)("encodes a %s record", (label, source, expected) => {
    const { hex } = compressOne(buildCMap({ records: [source] }));

    expect(outputBody(hex)).toBe(expected);
  });

  it("uses the optimized sequence form for consecutive cidchars", () => {
    const lines = Array.from(
      { length: 9 },
      (_, i) => `<${(0x20 + i).toString(16)}> ${100 + i}`
    );
    const source = buildCMap({
      records: [record(9, "cidchar", lines)],
    });

    const { hex } = compressOne(source);

    // 0x50 => type 2 with the sequence flag; then count, first entry and the
    // signed deltas of the following consecutive codes.
    expect(outputBody(hex)).toBe(`50092064${"00".repeat(8)}`);
  });

  it("merges adjacent blocks before encoding them", () => {
    const source = buildCMap({
      records: [
        record(2, "cidrange", ["<20> <2f> 100", "<40> <4f> 200"]),
        record(2, "cidrange", ["<60> <6f> 300", "<70> <7f> 400"]),
      ],
    });

    const { hex } = compressOne(source);

    expect(outputBody(hex)).toBe("6004200f64100f8148100f822c000f8310");
  });

  it("splits blocks whose entries have different code sizes", () => {
    const source = buildCMap({
      records: [
        record(2, "codespacerange", ["<00> <ff>", "<0000> <ffff>"]),
      ],
    });

    const { hex } = compressOne(source);

    expect(outputBody(hex)).toBe("000100817f0101000083ff7f");
  });
});

describe("compressCmaps file handling", () => {
  let roots;
  let logSpy;

  beforeEach(() => {
    roots = [];
    logSpy = jest.spyOn(console, "log").mockImplementation(() => {});
  });

  afterEach(() => {
    logSpy.mockRestore();
    for (const root of roots) {
      fs.rmSync(root, { recursive: true, force: true });
    }
  });

  function makeDirectories() {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), "pdfjs-cmapscompress-"));
    roots.push(root);
    const sourceDir = path.join(root, "source");
    const destDir = path.join(root, "dest");
    fs.mkdirSync(sourceDir);
    fs.mkdirSync(destDir);
    return { sourceDir, destDir };
  }

  it("creates one .bcmap file per source file without an extension", () => {
    const { sourceDir, destDir } = makeDirectories();
    fs.writeFileSync(path.join(sourceDir, "alpha"), buildCMap());
    fs.writeFileSync(path.join(sourceDir, "beta"), buildCMap());
    fs.writeFileSync(path.join(sourceDir, "skip.me"), buildCMap());
    fs.writeFileSync(path.join(sourceDir, ".hidden"), buildCMap());

    compressCmaps(sourceDir, destDir);

    expect(fs.readdirSync(destDir).sort()).toEqual([
      "alpha.bcmap",
      "beta.bcmap",
    ]);
  });

  it("logs the original and compressed sizes for every processed file", () => {
    const { sourceDir, destDir } = makeDirectories();
    const alpha = buildCMap({
      records: [record(1, "cidchar", ["<20> 100"])],
    });
    const beta = buildCMap({ type: 2, wmode: 1 });
    fs.writeFileSync(path.join(sourceDir, "alpha"), alpha);
    fs.writeFileSync(path.join(sourceDir, "beta"), beta);

    compressCmaps(sourceDir, destDir);

    expect(logSpy).toHaveBeenCalledTimes(2);
    const messages = logSpy.mock.calls.map(([message]) => message).sort();
    const expected = ["alpha", "beta"]
      .map(name => {
        const orig = fs.statSync(path.join(sourceDir, name)).size;
        const packed = fs.statSync(path.join(destDir, `${name}.bcmap`)).size;
        const ratio = ((packed / orig) * 100).toFixed(1);
        return `Compressing ${name}: ${orig} vs ${packed} ${ratio}%`;
      })
      .sort();

    expect(messages).toEqual(expected);
  });

  it("does nothing for an empty source directory", () => {
    const { sourceDir, destDir } = makeDirectories();

    compressCmaps(sourceDir, destDir);

    expect(fs.readdirSync(destDir)).toEqual([]);
    expect(logSpy).not.toHaveBeenCalled();
  });

  it("propagates CMap parsing errors without writing a destination file", () => {
    const { sourceDir, destDir } = makeDirectories();
    fs.writeFileSync(path.join(sourceDir, "broken"), "not a CMap at all");

    expect(() => compressCmaps(sourceDir, destDir)).toThrow(
      "cmap was not found"
    );
    expect(fs.existsSync(path.join(destDir, "broken.bcmap"))).toBe(false);
  });
});
