import { createCanvas } from '@napi-rs/canvas';
import { SignatureExtractor } from './src/display/editor/drawers/signaturedraw.js';
class TestOffscreenCanvas {
  constructor(width,height){ this.canvas=createCanvas(width,height); this.width=width; this.height=height; }
  getContext(type,opts){ return this.canvas.getContext(type,opts); }
  transferToImageBitmap(){ return this.canvas; }
}
globalThis.OffscreenCanvas=TestOffscreenCanvas;
const bitmap=createCanvas(64,64);
const ctx=bitmap.getContext('2d');
ctx.fillStyle='white';ctx.fillRect(0,0,64,64);ctx.fillStyle='black';ctx.beginPath();ctx.arc(32,32,15,0,Math.PI*2);ctx.fill();
const result=SignatureExtractor.process(bitmap,100,50,0,0.005);
console.log('process result',!!result,result && {curves:result.newCurves.length, first:result.newCurves[0]?.slice(0,8), box:Array.from(result.outline.box), path:result.outline.toSVGPath().slice(0,120), width:result.width,height:result.height,thickness:result.thickness,areContours:result.areContours,cls:result.outline.constructor.name});
const empty=createCanvas(32,32); const ec=empty.getContext('2d');ec.fillStyle='white';ec.fillRect(0,0,32,32);
console.log('empty',SignatureExtractor.process(empty,100,100,0,0));
// base64 polyfill
if (!Uint8Array.prototype.toBase64) Object.defineProperty(Uint8Array.prototype,'toBase64',{configurable:true,value:function(){return Buffer.from(this.buffer,this.byteOffset,this.byteLength).toString('base64')}});
if (!Uint8Array.fromBase64) Object.defineProperty(Uint8Array,'fromBase64',{configurable:true,value:function(s){return new Uint8Array(Buffer.from(s,'base64'))}});
const compressed=await SignatureExtractor.compressSignature({outlines:[[10,20,12,24,15,30],[1,2,3,4]],areContours:false,thickness:12.9,width:100,height:50});
console.log('compressed',compressed.slice(0,20),compressed.length);
const decoded=await SignatureExtractor.decompressSignature(compressed);
console.log('decoded',decoded && {areContours:decoded.areContours,thickness:decoded.thickness,width:decoded.width,height:decoded.height,outlines:decoded.outlines.map(a=>Array.from(a))});
console.log('bad',await SignatureExtractor.decompressSignature('not-valid!!'));
// int16
const c16=await SignatureExtractor.compressSignature({outlines:[[0,0,200,200,400,100]],areContours:true,thickness:0,width:500,height:500});
console.log('c16 decoded',(await SignatureExtractor.decompressSignature(c16)).outlines.map(a=>Array.from(a)));
EOF"}

