import {
  FreeDrawOutline,
  FreeDrawOutliner,
} from "../../../../src/display/editor/drawers/freedraw.js";

const BOX = [0, 0, 100, 100];

function createSquareOutline() {
  const outline = new Float32Array([
    NaN,
    NaN,
    NaN,
    NaN,
    10,
    10,
    NaN,
    NaN,
    NaN,
    NaN,
    30,
    10,
    NaN,
    NaN,
    NaN,
    NaN,
    30,
    30,
    NaN,
    NaN,
    NaN,
    NaN,
    10,
    30,
  ]);
  const points = new Float32Array([10, 10, 30, 10, 30, 30]);
  return new FreeDrawOutline(outline, points, BOX, 1, 0, true);
}

describe("FreeDrawOutliner", () => {
  test("starts empty and ignores points closer than the minimum distance", () => {
    const outliner = new FreeDrawOutliner(10, 10, BOX, 1, 2, true);

    expect(outliner.isEmpty()).toBe(true);
    expect(outliner.isCancellable()).toBe(true);
    expect(outliner.toSVGPath()).toBe("");
    expect(outliner.add(15, 10)).toBe(false);
    expect(outliner.isEmpty()).toBe(true);
    expect(outliner.toSVGPath()).toBe("");
  });

  test("accepts a sufficiently distant point and renders a closed capsule", () => {
    const outliner = new FreeDrawOutliner(10, 10, BOX, 1, 2, true);

    expect(outliner.add(30, 10)).toBe(true);
    expect(outliner.isEmpty()).toBe(false);
    expect(outliner.toSVGPath()).toBe(
      "M0.1 0.12 L0.22 0.12 L0.3 0.12 L0.3 0.08 L0.22 0.08 L0.1 0.08 Z"
    );
  });

  test("is cancellable through four accepted points and not after a fifth", () => {
    const outliner = new FreeDrawOutliner(0, 0, BOX, 1, 1, true);

    for (const x of [20, 40, 60, 80]) {
      expect(outliner.add(x, 0)).toBe(true);
    }
    expect(outliner.isCancellable()).toBe(true);

    expect(outliner.add(100, 0)).toBe(true);
    expect(outliner.isCancellable()).toBe(false);
  });

  test("renders curves when the stroke changes direction", () => {
    const outliner = new FreeDrawOutliner(10, 10, BOX, 1, 2, true);

    outliner.add(50, 10);
    outliner.add(50, 50);
    outliner.add(10, 50);

    const path = outliner.toSVGPath();
    expect(path).toMatch(/^M0\.1 0\.12 C/);
    expect(path).toContain("C");
    expect(path.endsWith(" Z")).toBe(true);
  });

  test("removeLastElement resets the drawing state", () => {
    const outliner = new FreeDrawOutliner(10, 10, BOX, 1, 2, true);
    outliner.add(30, 10);

    expect(outliner.removeLastElement()).toEqual({ path: { d: "" } });
    expect(outliner.isEmpty()).toBe(true);
    expect(outliner.isCancellable()).toBe(true);
    expect(outliner.toSVGPath()).toBe("");
  });

  test("getOutlines normalizes the stroke and preserves its geometry", () => {
    const outliner = new FreeDrawOutliner(10, 10, BOX, 1, 2, true);
    outliner.add(50, 10);
    outliner.add(50, 50);
    outliner.add(10, 50);

    const outline = outliner.getOutlines();
    expect(outline).toBeInstanceOf(FreeDrawOutline);

    const box = Array.from(outline.box);
    expect(box[0]).toBeCloseTo(0.096, 6);
    expect(box[1]).toBeCloseTo(0.08, 6);
    expect(box[2]).toBeCloseTo(0.37358, 5);
    expect(box[3]).toBeCloseTo(0.439596, 5);
    expect(outline.toSVGPath()).toContain("C");
    expect(outline.toSVGPath().endsWith("Z")).toBe(true);

    const serialized = outline.serialize([0, 0, 1, 1], 0);
    expect(serialized.outline).toHaveLength(36);
    expect(serialized.points).toHaveLength(1);
    expect(serialized.points[0]).toHaveLength(8);
  });
});

describe("FreeDrawOutline", () => {
  test("computes its bounding box and normalized path on construction", () => {
    const outline = createSquareOutline();

    expect(Array.from(outline.box)).toEqual([10, 10, 20, 20]);
    expect(outline.firstPoint).toEqual([30, 10]);
    expect(outline.lastPoint).toEqual([30, 30]);
    expect(outline.toSVGPath()).toBe("M0 0 L1 0 L1 1 L0 1 Z");
  });

  test.each([
    [0, [0, 100, 100, 100, 100, 0]],
    [90, [0, 0, 0, 100, 100, 100]],
    [180, [100, 0, 0, 0, 0, 100]],
    [270, [100, 100, 100, 0, 0, 0]],
  ])("serializes the normalized points for rotation %i", (rotation, expected) => {
    const outline = createSquareOutline();
    const serialized = outline.serialize([0, 0, 100, 100], rotation);

    expect(serialized.points).toEqual([expected]);
    expect(serialized.outline.filter(Number.isFinite)).toEqual([
      expected[0],
      expected[1],
      expected[2],
      expected[3],
      expected[4],
      expected[5],
      expected[6] ?? expected[0],
      expected[7] ?? expected[1],
    ]);
    expect(serialized.outline.slice(0, 4).every(Number.isNaN)).toBe(true);
  });

  test("updateThickness mutates and returns its bounding box", () => {
    const outline = createSquareOutline();
    const box = outline.box;
    const oldPath = outline.toSVGPath();

    const updatedBox = outline.updateThickness(8);

    expect(updatedBox).toBe(box);
    expect(box[2]).toBeGreaterThan(20);
    expect(box[3]).toBeGreaterThan(20);
    expect(outline.toSVGPath()).not.toBe(oldPath);
    expect(outline.firstPoint[0]).toBeCloseTo(10, 5);
  });

  test("getNewOutline returns an independent outline with the requested margin", () => {
    const outline = createSquareOutline();
    const newOutline = outline.getNewOutline(8, 0.01);

    expect(newOutline).toBeInstanceOf(FreeDrawOutline);
    expect(newOutline).not.toBe(outline);
    expect(Array.from(newOutline.box)).not.toEqual(Array.from(outline.box));
    expect(newOutline.toSVGPath()).toBe("M0 0 L1 0 L1 1 L0 1 Z");
  });
});
