import {
  FreeHighlightDrawer,
  HighlightOutline,
  HighlightOutliner,
} from "../../../../src/display/editor/drawers/highlight.js";
import { Outline } from "../../../../src/display/editor/drawers/outline.js";

const BOX = [0, 0, 100, 100];

function makeFreeHighlightDrawer() {
  const drawer = new FreeHighlightDrawer(
    10,
    10,
    BOX,
    1,
    5,
    true,
    /* innerMargin = */ 0.001
  );
  drawer.add(30, 10);
  drawer.addPoints([40, 20, 50, 40, 60, 50]);
  return drawer;
}

describe("HighlightOutliner", () => {
  test("builds a normalized rectangle with LTR first and last points", () => {
    const outline = new HighlightOutliner([
      { x: 10, y: 20, width: 30, height: 10 },
    ]).getOutlines();

    expect(outline).toBeInstanceOf(HighlightOutline);
    expect(Array.from(outline.box)).toEqual([10, 20, 30, 10]);
    expect(outline.firstPoint).toEqual([40, 20]);
    expect(outline.lastPoint).toEqual([40, 30]);
    expect(outline.toSVGPath()).toBe("M0 1 V0 H1 V1 Z");
  });

  test("selects the opposite start and end points for RTL boxes", () => {
    const outline = new HighlightOutliner(
      [{ x: 10, y: 20, width: 30, height: 10 }],
      0,
      0,
      false
    ).getOutlines();

    expect(outline.firstPoint).toEqual([10, 20]);
    expect(outline.lastPoint).toEqual([10, 30]);
    expect(outline.toSVGPath()).toBe("M0 1 V0 H1 V1 Z");
  });

  test("merges touching boxes into one outline", () => {
    const outline = new HighlightOutliner([
      { x: 0, y: 0, width: 10, height: 10 },
      { x: 10, y: 0, width: 10, height: 10 },
    ]).getOutlines();

    expect(Array.from(outline.box)).toEqual([0, 0, 20, 10]);
    expect(outline.toSVGPath().match(/Z/g)).toHaveLength(1);
    expect(outline.serialize([0, 0, 100, 100], 0)).toHaveLength(1);
  });

  test("keeps disjoint boxes as separate polygons", () => {
    const outline = new HighlightOutliner([
      { x: 0, y: 0, width: 10, height: 10 },
      { x: 30, y: 0, width: 10, height: 10 },
    ]).getOutlines();

    expect(Array.from(outline.box)).toEqual([0, 0, 40, 10]);
    expect(outline.toSVGPath().match(/Z/g)).toHaveLength(2);
    expect(outline.serialize([0, 0, 100, 100], 0)).toHaveLength(2);
  });

  test("serializes normalized polygons into a requested page rectangle", () => {
    const outline = new HighlightOutliner([
      { x: 10, y: 20, width: 30, height: 10 },
    ]).getOutlines();

    expect(outline.serialize([100, 200, 400, 600], 0)).toEqual([
      [100, 200, 100, 600, 400, 600, 400, 200],
    ]);
  });
});

describe("HighlightOutline", () => {
  const boxes = [
    { x: 0.1, y: 0.2, width: 0.3, height: 0.1 },
    { x: 0.4, y: 0.2, width: 0.2, height: 0.1 },
  ];

  test("build creates regular and focus outlines from selection boxes", () => {
    const outline = HighlightOutline.build(boxes, true);

    expect(outline).toBeInstanceOf(HighlightOutline);
    expect(outline.isFree).toBe(false);
    expect(outline.focusOutline).toBeInstanceOf(HighlightOutline);
    expect(outline.focusOutline).not.toBe(outline);
    expect(outline.toSVGPath().match(/Z/g)).toHaveLength(1);
    expect(outline.focusOutline.toSVGPath()).not.toBe(outline.toSVGPath());
  });

  test("exposes highlight SVG and rotation metadata", () => {
    const outline = HighlightOutline.build(boxes, true);
    const properties = outline.defaultSVGProperties;

    expect(properties.bbox).toBe(outline.box);
    expect(properties.root).toEqual({ viewBox: "0 0 1 1" });
    expect(properties.rootClass).toEqual({ highlight: true, free: false });
    expect(properties.path.d).toBe(outline.toSVGPath());
