    expect(properties.root).toEqual({ "data-main-rotation": 90 });
    expect(properties.rootClass).toEqual({
      highlightOutline: true,
      free: false,
    });
    expect(properties.path.d).toBe(outline.focusOutline.toSVGPath());
  });

