      root: { "data-main-rotation": 270 },
    });
  });

  test("exposes focus SVG metadata with a rotated focus box", () => {
    const outline = HighlightOutline.build(boxes, true);
    const properties = outline.getFocusSVGProperties(90);

    expect(properties.bbox).toEqual(
      Outline._rotateBox(outline.focusOutline.box, 90)
    );
    expect(properties.root).toEqual({ "data-main-rotation": 90 });
    expect(properties.rootClass).toEqual({
      highlightOutline: true,
      free: false,
    });
    expect(properties.path.d).toBe(outline.focusOutline.toSVGPath());
  });

  test("serializeQuadPoints maps every original box to page coordinates", () => {
    const outline = HighlightOutline.build(boxes, true);

    expect(
      Array.from(outline.serializeQuadPoints([10, 20], [100, 200]))
    ).toEqual([
      20, 180, 50, 180, 20, 160, 50, 160, 50, 180, 70, 180, 50, 160, 70, 160,
    ]);
