describe("FreeHighlightDrawer", () => {
  test("reports initial state and ignores points that are too close", () => {
    const drawer = new FreeHighlightDrawer(10, 10, BOX, 1, 5, true, 0.001);

    expect(drawer.isEmpty()).toBe(true);
    expect(drawer.isCancellable()).toBe(true);
    expect(drawer.add(15, 10)).toBeNull();
    expect(drawer.addPoints([12, 10, 15, 10])).toBeNull();
    expect(drawer.end()).toBeNull();
  });

  test("returns SVG updates for valid points and batches", () => {
    const drawer = new FreeHighlightDrawer(10, 10, BOX, 1, 5, true, 0.001);

    expect(drawer.add(30, 10).path.d).toContain("M0.1 0.15");
    expect(drawer.addPoints([40, 20, 50, 40]).path.d).toContain("C");
    expect(drawer.updateProperty("thickness", 9)).toBeNull();
