    expect(focusProperties.root).toEqual({ "data-main-rotation": 180 });
    expect(focusProperties.rootClass).toEqual({
      highlightOutline: true,
      free: true,
    });
  });

  test("thickness updates rebuild the free highlight and focus geometry", () => {
    const outline = makeFreeHighlightDrawer().getOutlines();
    const oldPath = outline.toSVGPath();
    const oldFocusPath = outline.focusOutline.toSVGPath();
    const oldHeight = outline.box[3];

    const updatedBox = outline.updateProperty("thickness", 12);

    expect(updatedBox).toBe(outline.box);
    expect(outline.box[3]).toBeGreaterThan(oldHeight);
    expect(outline.toSVGPath()).not.toBe(oldPath);
    expect(outline.focusOutline.toSVGPath()).not.toBe(oldFocusPath);
    expect(outline.updateProperty("fill", "red")).toBeNull();
    expect(outline.updateRotation(90)).toEqual({
      root: { "data-main-rotation": 90 },
    });
    expect(outline.getPathResizedSVGProperties([0, 0, 1, 1])).toEqual({
      path: { d: outline.toSVGPath() },
    });
  });
});
