import {
  InkDrawOutline,
  InkDrawOutliner,
} from "../../../../src/display/editor/drawers/inkdraw.js";

function buildSquareOutline({ rotation = 0, thickness = 0 } = {}) {
  const outline = new InkDrawOutline();
  outline.build(
    [
      {
        line: new Float32Array([
          NaN,
          NaN,
          NaN,
          NaN,
          0.25,
          0.25,
          NaN,
          NaN,
          NaN,
          NaN,
          0.75,
          0.75,
        ]),
        points: new Float32Array([0.25, 0.25, 0.75, 0.75]),
      },
    ],
    100,
    100,
    1,
    rotation,
    thickness,
    0
  );
  return outline;
}

function drawThreePoints(rotation = 0, thickness = 2) {
  const outliner = new InkDrawOutliner(20, 30, 100, 200, rotation, thickness);
  outliner.add(40, 50);
  outliner.add(60, 80);
  outliner.add(30, 100);
  return outliner;
}

describe("InkDrawOutliner", () => {
  test("exposes drawing defaults and cancellable state", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 2);

    expect(outliner.isEmpty()).toBe(false);
    expect(outliner.isCancellable()).toBe(true);
    expect(outliner.defaultSVGProperties).toEqual({
      root: { viewBox: "0 0 10000 10000" },
      rootClass: { draw: true },
      bbox: [0, 0, 1, 1],
    });
  });

  test("ignores points at or below the two-pixel threshold", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 2);

    expect(outliner.add(12, 10).path.d).toBe(
      " M 1000 1000 L 1200 1000"
    );
    expect(outliner.end()).toEqual({ path: { d: " M 1000 1000 Z" } });
  });

  test("shows a transient tip while drawing and removes it when ending", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 2);

    expect(outliner.add(13, 10).path.d).toBe(
      " M 1000 1000 L 1300 1000 L 1300 1000"
    );
    expect(outliner.end().path.d).toBe(" M 1000 1000 L 1300 1000");
  });

  test("addPoints produces the same committed path as individual adds", () => {
    const batch = new InkDrawOutliner(10, 10, 100, 100, 0, 2);
    const individual = new InkDrawOutliner(10, 10, 100, 100, 0, 2);
    const points = [30, 10, 50, 50, 20, 70];

    const batchUpdate = batch.addPoints(points);
    for (let i = 0; i < points.length; i += 2) {
      individual.add(points[i], points[i + 1]);
    }

    expect(batchUpdate.path.d).toBe(individual.add(20, 70).path.d);
    expect(batch.end()).toEqual(individual.end());
  });

  test("stroke-width updates affect the finalized outline", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 2);
    outliner.updateProperty("stroke-width", 12);
    outliner.updateProperty("unknown", 50);
    outliner.add(30, 10);
    outliner.add(50, 50);

    const outline = outliner.getOutlines(100, 100, 1, 0.01);
    expect(outline.thickness).toBe(12);
  });

  test("supports multiple strokes and finalizes all of them", () => {
    const outliner = new InkDrawOutliner(10, 10, 100, 100, 0, 2);
    outliner.add(30, 10);
    outliner.add(30, 30);
    expect(outliner.startNew(60, 60, 100, 100, 0)).toBeNull();
    outliner.add(80, 80);
    outliner.add(80, 50);

    const outline = outliner.getOutlines(100, 100, 1, 0);
    expect(outline.toSVGPath().match(/M/g)).toHaveLength(2);
  });

  test.each([
    [0, 0.0899, 0.0899, 0.3602, 0.5202, "M2000 3000"],
    [90, 0.3899, 0.0899, 0.5202, 0.3602, "M7000 1000"],
    [180, 0.5499, 0.3899, 0.3602, 0.5202, "M8000 8500"],
    [270, 0.0899, 0.5499, 0.5202, 0.3602, "M3000 9000"],
  ])(
    "normalizes and rotates a stroke for page rotation %i",
    (rotation, x, y, width, height, start) => {
      const outline = drawThreePoints(rotation).getOutlines(
        100,
        200,
        1,
        0.01
      );
      const box = Array.from(outline.box);

      expect(box[0]).toBeCloseTo(x, 4);
      expect(box[1]).toBeCloseTo(y, 4);
      expect(box[2]).toBeCloseTo(width, 4);
      expect(box[3]).toBeCloseTo(height, 4);
      expect(outline.toSVGPath().startsWith(start)).toBe(true);
    }
  );
});

describe("InkDrawOutline", () => {
  test("builds normalized path and default SVG properties", () => {
    const outline = buildSquareOutline();

    expect(Array.from(outline.box)).toEqual([0.25, 0.25, 0.5, 0.5]);
    expect(outline.thickness).toBe(0);
    expect(outline.viewBox).toBe("2500 2500 5000 5000");
    expect(outline.toSVGPath()).toBe("M2500 2500L7500 7500");
    expect(outline.defaultSVGProperties).toEqual({
      root: { viewBox: "2500 2500 5000 5000" },
      rootClass: { draw: true },
      path: {
        d: "M2500 2500L7500 7500",
        "transform-origin": "2500 2500",
        transform: null,
      },
      bbox: outline.box,
    });
    expect(outline.defaultProperties).toEqual({
      root: { viewBox: "2500 2500 5000 5000" },
      path: { "transform-origin": "2500 2500" },
    });
  });

  test.each([
    [0, "", { path: { transform: "" } }],
    [90, "matrix(0 1 -1 0 5000 0)", { path: { transform: "matrix(0 1 -1 0 5000 0)" } }],
    [180, "matrix(-1 0 0 -1 5000 5000)", { path: { transform: "matrix(-1 0 0 -1 5000 5000)" } }],
    [270, "matrix(0 -1 1 0 0 5000)", { path: { transform: "matrix(0 -1 1 0 0 5000)" } }],
  ])("updates the rotation transform for %i degrees", (rotation, transform, result) => {
    const outline = buildSquareOutline();

    expect(outline.updateRotation(rotation)).toEqual(result);
    expect(outline.rotationTransform).toBe(transform);
  });

  test("updates thickness and bounding box through updateProperty", () => {
    const outline = buildSquareOutline({ thickness: 10 });
    const box = outline.box;

    expect(Array.from(box)).toEqual([0.2, 0.2, 0.6, 0.6]);
    expect(outline.updateProperty("unknown", 4)).toBeNull();
    expect(outline.updateProperty("stroke-width", 20)).toBe(box);
    expect(outline.thickness).toBe(20);
    expect(Array.from(box)).toEqual([0.15, 0.15, 0.7, 0.7]);
  });

  test("updateParentDimensions adjusts margins without replacing the box", () => {
    const outline = buildSquareOutline({ thickness: 10 });
    const box = outline.box;

    const result = outline.updateParentDimensions([200, 100], 1);

    expect(result).toBe(box);
    expect(box[0]).toBeCloseTo(0.225, 6);
    expect(box[1]).toBeCloseTo(0.2, 6);
    expect(box[2]).toBeCloseTo(0.55, 6);
    expect(box[3]).toBeCloseTo(0.6, 6);
  });

  test("builds resize transforms with the current rotation", () => {
    const outline = buildSquareOutline();
    outline.updateRotation(90);

    const properties = outline.getPathResizingSVGProperties([
      0.1, 0.1, 0.6, 0.6,
    ]);

    expect(properties.path["transform-origin"]).toBe("2500 2500");
    expect(properties.path.transform).toMatch(
      /^matrix\(0 1 -1 0 5000 0\) scale\(/
    );
    expect(properties.path.transform).toContain("scale(1.2 1.2)");
  });

  test("applies a resize and returns the updated SVG", () => {
    const outline = buildSquareOutline();

    const properties = outline.getPathResizedSVGProperties([
      0.1, 0.2, 0.4, 0.3,
    ]);

    expect(Array.from(outline.box)).toEqual([0.1, 0.2, 0.4, 0.3]);
    expect(properties.root.viewBox).toBe(outline.viewBox);
    expect(properties.path.d).toBe(outline.toSVGPath());
    expect(properties.path["transform-origin"]).toBe("1000 2000");
  });

  test("translates an outline and updates its origin", () => {
    const outline = buildSquareOutline();

    const properties = outline.getPathTranslatedSVGProperties(
      [0.5, 0.5],
      [100, 100]
    );

    expect(Array.from(outline.box)).toEqual([0.5, 0.5, 0.5, 0.5]);
    expect(properties.path["transform-origin"]).toBe("5000 5000");
    expect(properties.path.d).toBe(outline.toSVGPath());
    expect(properties.root.viewBox).toBe(outline.viewBox);
  });

  test("rescales an outline when parent dimensions change during translation", () => {
    const outline = buildSquareOutline({ thickness: 10 });
    outline.updateParentDimensions([200, 200], 1);

    outline.getPathTranslatedSVGProperties([0.5, 0.5], [200, 200]);

    expect(Array.from(outline.box)).toEqual([0.5, 0.5, 0.55, 0.55]);
  });

  test("serializes into page coordinates and can copy with plain arrays", () => {
    const outline = buildSquareOutline();
    const serialized = outline.serialize([10, 20, 100, 200], false);

    expect(serialized.rect).toEqual([35, 70, 85, 170]);
    expect(Array.from(serialized.lines[0])).toEqual([
      NaN,
      NaN,
      NaN,
      NaN,
      35,
      170,
      NaN,
      NaN,
      NaN,
      NaN,
      85,
      70,
    ]);
    expect(Array.from(serialized.points[0])).toEqual([35, 170, 85, 70]);

    const copied = outline.serialize([10, 20, 100, 200], true);
    expect(Array.isArray(copied.lines[0])).toBe(true);
    expect(Array.isArray(copied.points[0])).toBe(true);
  });

  test.each([0, 90, 180, 270])(
    "round-trips serialized ink paths at rotation %i",
    rotation => {
      const outline = drawThreePoints(rotation, 4).getOutlines(
        100,
        200,
        1,
        0.01
      );
      const paths = outline.serialize([10, 20, 100, 200], false);

      const restored = InkDrawOutline.deserialize(
        10,
        20,
        100,
        200,
        0.01,
        { paths, rotation, thickness: 4 }
      );

      expect(restored.toSVGPath()).toBe(outline.toSVGPath());
      expect(restored.thickness).toBe(4);
      Array.from(outline.box).forEach((value, index) => {
        expect(restored.box[index]).toBeCloseTo(value, 5);
      });
    }
  );

  test.each([
    [[20, 40], "M2000 8000Z"],
    [
      [20, 40, 80, 160],
      "M2000 8000L8000 2000",
    ],
    [
      [20, 40, 50, 100, 80, 160],
      "M2000 8000C4500 5500 5500 4500 6500 3500",
    ],
  ])("deserializes point-only paths of length %#", (points, expected) => {
    const outline = InkDrawOutline.deserialize(
      0,
      0,
      100,
      200,
      0.001,
      {
        paths: { points: [new Float32Array(points)] },
        rotation: 0,
        thickness: 0,
      }
    );

    expect(outline.toSVGPath()).toBe(expected);
  });
});
