describe("SignatureExtractor bitmap processing", () => {
  test("extracts closed contours from a drawn bitmap", () => {
    const bitmap = makeBitmap(64, 64, context => {
      context.fillStyle = "black";
      context.beginPath();
      context.arc(32, 32, 15, 0, Math.PI * 2);
      context.fill();
    });

    const result = SignatureExtractor.process(bitmap, 100, 50, 0, 0.005);

    expect(result).not.toBeNull();
    expect(result.outline).toBeInstanceOf(ContourDrawOutline);
    expect(result.areContours).toBe(true);
    expect(result.thickness).toBe(0);
    expect(result.width).toBe(64);
    expect(result.height).toBe(64);
    expect(result.newCurves.length).toBeGreaterThan(0);
    expect(result.outline.toSVGPath().endsWith("Z")).toBe(true);

    const box = Array.from(result.outline.box);
    expect(box[0]).toBeGreaterThanOrEqual(0);
    expect(box[1]).toBeGreaterThanOrEqual(0);
    expect(box[2]).toBeGreaterThan(0);
    expect(box[3]).toBeGreaterThan(0);
    expect(box[0] + box[2]).toBeLessThanOrEqual(1);
    expect(box[1] + box[3]).toBeLessThanOrEqual(1);
  });

  test("honors the page rotation while processing a bitmap", () => {
    const bitmap = makeBitmap(64, 32, context => {
      context.fillStyle = "black";
      context.fillRect(10, 10, 20, 10);
