    const result = SignatureExtractor.process(bitmap, 100, 50, 90, 0);

    expect(result).not.toBeNull();
    expect(result.outline).toBeInstanceOf(ContourDrawOutline);
    expect(result.newCurves.length).toBeGreaterThan(0);
    expect(Array.from(result.outline.box).every(value => value >= 0 && value <= 1)).toBe(
      true
    );
  });

  test("returns null for an empty bitmap", () => {
    const bitmap = makeBitmap(32, 32, () => {});

    expect(SignatureExtractor.process(bitmap, 100, 100, 0, 0)).toBeNull();
  });

