    expect(result.outline.toSVGPath().endsWith("Z")).toBe(true);
  });
});

describe("SignatureExtractor compression", () => {
  test.each([
    [
      "8-bit coordinate differences",
      [[10, 20, 12, 24, 15, 30], [1, 2, 3, 4]],
      false,
      12.9,
    ],
    [
      "16-bit coordinate differences",
      [[0, 0, 200, 200, 400, 100]],
      true,
      3.2,
    ],
    [
      "32-bit coordinate differences",
      [[0, 0, 40000, 0, 80000, 40000]],
      true,
      0,
    ],
  ])(
    "round-trips outlines using %s",
    async (_name, outlines, areContours, thickness) => {
      const compressed = await SignatureExtractor.compressSignature({
        outlines,
        areContours,
        thickness,
        width: 100,
        height: 50,
      });

      expect(typeof compressed).toBe("string");
      expect(compressed.length).toBeGreaterThan(0);

      const decoded = await SignatureExtractor.decompressSignature(compressed);
      expect(decoded.areContours).toBe(areContours);
      expect(decoded.thickness).toBe(Math.floor(thickness));
      expect(decoded.width).toBe(100);
      expect(decoded.height).toBe(50);
      expect(decoded.outlines.map(outline => Array.from(outline))).toEqual(
        outlines
      );
    }
  );

  test("round-trips an empty outline list", async () => {
    const compressed = await SignatureExtractor.compressSignature({
      outlines: [],
      areContours: true,
      thickness: undefined,
      width: 2,
      height: 3,
    });

    const decoded = await SignatureExtractor.decompressSignature(compressed);
    expect(decoded.areContours).toBe(true);
    expect(decoded.thickness).toBe(0);
    expect(decoded.width).toBe(2);
    expect(decoded.height).toBe(3);
    expect(decoded.outlines).toEqual([]);
  });

  test("returns null and warns for malformed data", async () => {
    const warning = jest.spyOn(console, "warn").mockImplementation(() => {});

    await expect(
      SignatureExtractor.decompressSignature("not-valid-base64")
    ).resolves.toBeNull();
    expect(warning).toHaveBeenCalledWith(
      expect.stringContaining("decompressSignature")
    );

    warning.mockRestore();
  });

  test("rejects an unsupported format version", async () => {
    const warning = jest.spyOn(console, "warn").mockImplementation(() => {});
    const header = new Uint32Array([32, 1, 10, 10, 0, 0, 0, 0]);
    const payload = await deflate(new Uint8Array(header.buffer));
    const signature = Buffer.from(payload).toString("base64");

    await expect(
      SignatureExtractor.decompressSignature(signature)
    ).resolves.toBeNull();
    expect(warning).toHaveBeenCalledWith(
      expect.stringContaining("Invalid version: 1")
    );

    warning.mockRestore();
  });
});
